import { createSlice } from "@reduxjs/toolkit";

// The httpOnly cookie is the real credential; this localStorage copy of the
// user profile is only an optimistic cache so that a page refresh restores the
// UI session instantly (no redirect-to-login flash) before /myprofile
// re-validates against the cookie. If the server rejects the cookie, the
// cache is cleared and the user is logged out for real.
const AUTH_KEY = 'vijaycart_auth';

const readAuth = () => {
    try {
        const raw = localStorage.getItem(AUTH_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (parsed && parsed.isAuthenticated && parsed.user) return parsed;
        return null;
    } catch {
        return null;
    }
};

const persistAuth = (user) => {
    try {
        localStorage.setItem(AUTH_KEY, JSON.stringify({ isAuthenticated: true, user }));
    } catch {
        /* storage unavailable — cookie session still works for the current tab */
    }
};

const clearAuth = () => {
    try {
        localStorage.removeItem(AUTH_KEY);
    } catch {
        /* ignore */
    }
};

const savedAuth = readAuth();

const authSlice = createSlice({
    name: 'auth',
    initialState: {
        loading: true,
        isAuthenticated: !!savedAuth,
        user: savedAuth ? savedAuth.user : null
    },
    reducers: {
        loginRequest(state, action){
            return {
                ...state,
                loading: true,
            }
        },
        loginSuccess(state, action){
            persistAuth(action.payload.user);
            return {
                loading: false,
                isAuthenticated: true,
                user: action.payload.user
            }
        },
        loginFail(state, action){
            return {
                ...state,
                loading: false,
                error:  action.payload
            }
        },
        clearError(state, action){
            return {
                ...state,
                error:  null
            }
        },
        registerRequest(state, action){
            return {
                ...state,
                loading: true,
            }
        },
        registerSuccess(state, action){
            persistAuth(action.payload.user);
            return {
                loading: false,
                isAuthenticated: true,
                user: action.payload.user
            }
        },
        registerFail(state, action){
            return {
                ...state,
                loading: false,
                error:  action.payload
            }
        },
        loadUserRequest(state, action){
            // Keep the previously known session while re-validating. Setting
            // isAuthenticated=false here would flash a logged-out state on
            // every refresh before /myprofile responds.
            return {
                ...state,
                loading: true,
            }
        },
        loadUserSuccess(state, action){
            persistAuth(action.payload.user);
            return {
                loading: false,
                isAuthenticated: true,
                user: action.payload.user
            }
        },
        loadUserFail(state, action){
            const { status, message } = action.payload || {};
            // Only treat an explicit auth rejection as a logout. A transient
            // network/500 error must not kick the user out of a valid session.
            const isAuthError = status === 401 || status === 403
                || (status === 400 && /login first|token|unauthorized|not allowed/i.test(String(message || '')));
            if (isAuthError) {
                clearAuth();
                return {
                    loading: false,
                    isAuthenticated: false,
                    error: message
                };
            }
            return {
                ...state,
                loading: false,
                error: message
            };
        },
        logoutSuccess(state, action){
            clearAuth();
            return {
                loading: false,
                isAuthenticated: false,
                user: null
            }
        },
        logoutFail(state, action){
            return {
                ...state,
                error:  action.payload
            }
        },
        updateProfileRequest(state, action){
            return {
                ...state,
                loading: true,
                isUpdated: false
            }
        },
        updateProfileSuccess(state, action){
            persistAuth(action.payload.user);
            return {
                ...state,
                loading: false,
                user: action.payload.user,
                isUpdated: true
            }
        },
        updateProfileFail(state, action){
            return {
                ...state,
                loading: false,
                error:  action.payload
            }
        },
        clearUpdateProfile(state, action){
            return {
                ...state,
                isUpdated: false
            }
        },

        updatePasswordRequest(state, action){
            return {
                ...state,
                loading: true,
                isUpdated: false
            }
        },
        updatePasswordSuccess(state, action){
            return {
                ...state,
                loading: false,
                isUpdated: true
            }
        },
        updatePasswordFail(state, action){
            return {
                ...state,
                loading: false,
                error:  action.payload
            }
        },
        forgotPasswordRequest(state, action){
            return {
                ...state,
                loading: true,
                message: null
            }
        },
        forgotPasswordSuccess(state, action){
            return {
                ...state,
                loading: false,
                message: action.payload.message
            }
        },
        forgotPasswordFail(state, action){
            return {
                ...state,
                loading: false,
                error: action.payload
            }
        },
        resetPasswordRequest(state, action){
            return {
                ...state,
                loading: true,
            }
        },
        resetPasswordSuccess(state, action){
            persistAuth(action.payload.user);
            return {
                ...state,
                loading: false,
                isAuthenticated: true,
                user: action.payload.user
            }
        },
        resetPasswordFail(state, action){
            return {
                ...state,
                loading: false,
                error: action.payload
            }
        },
        
    }
});

const { actions, reducer } = authSlice;

export const { 
    loginRequest, 
    loginSuccess, 
    loginFail, 
    clearError,
    registerRequest,
    registerSuccess,
    registerFail,
    loadUserRequest,
    loadUserSuccess,
    loadUserFail,
    logoutFail,
    logoutSuccess,
    updateProfileFail,
    updateProfileRequest,
    updateProfileSuccess,
    clearUpdateProfile,
    updatePasswordFail,
    updatePasswordSuccess,
    updatePasswordRequest,
    forgotPasswordFail,
    forgotPasswordSuccess,
    forgotPasswordRequest,
    resetPasswordFail,
    resetPasswordRequest,
    resetPasswordSuccess,
    
 } = actions;

export default reducer;

